const SLO = 0.999;
const errorBudget = 1 - SLO;            // 0.001 = 0.1%
const windowDays = 30;
const budgetMinutes = errorBudget * windowDays * 24 * 60;
console.log('error budget fraction:', errorBudget);
console.log('budget minutes / 30d:', budgetMinutes.toFixed(1));

// Burn rate = (observed error ratio) / (error budget).
// A burn rate of 1 spends the whole 30-day budget in exactly 30 days.
const observedErrorRatio = 0.015;       // 1.5% errors right now
const burnRate = observedErrorRatio / errorBudget;
console.log('1h-window burn rate:', burnRate);

// At burn rate 15 the 30-day budget is gone in 30/15 = 2 days.
console.log('budget exhausted in (days):', (windowDays / burnRate).toFixed(2));
// >14.4 on the fast (1h) window is the Google SRE page threshold.
console.log('crosses fast-burn page threshold (14.4)?', burnRate > 14.4);
